clear;
clc;
close all;
set(0,'defaultAxesFontSize',16);

%%                         PLOT TRAJECTORY
% Description: using the ASCII trajectory generated by MSODP, plot
% trajectory over time and S/C altitude.
% 
% Author: Sergio Coll-Ibars
% Date: 04/01/2026
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

folder = "/Users/sergiocollibars/Documents/SC_trajectory/450km/";

% Constants
R_E = 6378e3; % Earth equatorial radius [m]

% Get only .txt files
files = dir(fullfile(folder, "*.txt"));
nfiles = numel(files);

% Preallocate as cell arrays first because file lengths may vary
t_all    = cell(nfiles, 1);
posA_all = cell(nfiles, 1);
velA_all = cell(nfiles, 1);
posB_all = cell(nfiles, 1);
velB_all = cell(nfiles, 1);

% UTC time vector
UTC_vec = strings(1, nfiles);
for k = 1:nfiles
    filename = files(k).name;
    filepath = fullfile(files(k).folder, files(k).name);

    fprintf('Reading %s\n', filename);

    [t, rA, vA, rB, vB] = read_pos_vel_txt(filepath);

    t_all{k}    = t;
    posA_all{k} = rA;
    velA_all{k} = vA;
    posB_all{k} = rB;
    velB_all{k} = vB;

    date_str = extractBefore(files(k).name, '_orbit.txt');
    
    UTC_vec(k) = string(date_str);
end

% Concatenate all files
t    = vertcat(t_all{:});
posA = vertcat(posA_all{:});
velA = vertcat(velA_all{:});
posB = vertcat(posB_all{:});
velB = vertcat(velB_all{:});

% Optional: sort by time
[t, idx] = sort(t);

posA = posA(idx, :);
velA = velA(idx, :);
posB = posB(idx, :);
velB = velB(idx, :);

% Optional: altitude above Earth surface
altA = vecnorm(posA, 2, 2) - R_E;
altB = vecnorm(posB, 2, 2) - R_E;

%% Earth ground coverage / ground track

% If t is seconds from the beginning of each file, use the first file date
% as the UTC epoch. If t already represents absolute time, modify this part.
JD = t;
UTC_time = datetime(JD, 'ConvertFrom', 'juliandate');
UTC_time.TimeZone = 'UTC';

rECEF = zeros(size(posA));
disp('Compute SC-A position in ECEF')
for k = 1:length(UTC_time)

    % Convert datetime to date vector: [year month day hour minute second]
    utc_vec = datevec(UTC_time(k));

    % Direction cosine matrix from ECI to ECEF
    C_ECEF_ECI = dcmeci2ecef('IAU-2000/2006', utc_vec);

    % Rotate inertial position into Earth-fixed frame
    rECEF(k,:) = (C_ECEF_ECI * posA(k,:).').';
end

% convert to Lon and Lat
llaA = ecef2lla(rECEF);   % [lat lon alt], degrees and meters

latA_deg = llaA(:,1);
lonA_deg = llaA(:,2);
altA_m   = llaA(:,3);


% plot coverage
figure(); hold on; grid on; box on;
plot(lonA_deg, latA_deg, '.', 'MarkerSize', 5);
xlabel('Longitude [deg]');
ylabel('Latitude [deg]');
title('Spacecraft Ground Coverage');
legend('S/C A', 'Location', 'best');

xlim([-180 180]);
ylim([-90 90]);
axis equal;

%% plot altitude + S/C separation
figure();
subplot(1, 2, 1);
plot(t, altA./1E3, 'LineWidth', 1.2, 'Color', 'b'); grid on; ylabel('[km]');
title('Altitude S/C A');
subplot(1, 2, 2)
plot(t, altB./1E3, 'LineWidth', 1.2, 'Color', 'r'); grid on; ylabel('[km]');
title('Altitude S/C B');

figure(); 
plot(t, (vecnorm(posA' -posB'))./1E3, 'LineWidth', 2); ylabel('[km]');
grid on; title('Relative distance between S/C');

disp('Mean altitude, S/C A: ' + string(mean(altA)./1E3));
disp('Mean altitude, S/C B: ' + string(mean(altB)./1E3));